-- Backend Engineering ("The Fracture") Act 20 -- "Files, Media & Object Storage" content.
-- Closes out the currently-authored range (Acts 1-20) inside Arc V (Protect & Prove).
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the same
-- campaigns -> operations -> missions -> dialogue -> objectives -> challenges -> hints
-- pattern as every prior Act.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be20', 'world-be-20', 'files-media-and-object-storage', '20A - Files, Media & Object Storage', 'A city resident''s twenty-gigabyte encrypted case archive fails at ninety-four percent on every attempt, silently, with no way to resume. Tracing why means learning how a file actually moves -- from a browser, through a server that was never built to hold it all at once, into storage that was.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be20-1', 'campaign-be20', 'the-upload-path', 'The Upload Path', 'Multipart forms, streaming uploads, large-file handling, object storage, S3 concepts and signed URLs -- how a file actually gets from a browser into durable storage without ever living in a server''s memory all at once.', 1),
  ('operation-be20-2', 'campaign-be20', 'serving-it-back-safely', 'Serving It Back, Safely', 'File metadata, CDN delivery, image processing pipelines, malware-scanning architecture and resumable uploads -- what happens to a file after it lands, and the one gap that turns a twenty-gigabyte upload into a silent failure.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be20-01', 'world-be-20', 'campaign-be20', 'operation-be20-1', 'multipart-forms', 'Multipart Forms', 'Every upload starts as a form nobody thinks about twice: multipart/form-data, splitting a request into named parts with a boundary string holding them apart. Get the boundary wrong and the whole body is unreadable.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"multipart-forms-sim"}'::jsonb, '{"xp":230,"credits":44}'::jsonb, false, 1),
  ('mission-be20-02', 'world-be-20', 'campaign-be20', 'operation-be20-1', 'streaming-uploads', 'Streaming Uploads', 'A request body doesn''t have to arrive all at once, and handling it doesn''t require holding all of it in memory either. Streaming reads it in pieces and forgets each piece the moment it''s used.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be20-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"streaming-uploads-sim"}'::jsonb, '{"xp":232,"credits":44}'::jsonb, false, 2),
  ('mission-be20-03', 'world-be-20', 'campaign-be20', 'operation-be20-1', 'large-file-handling', 'Large File Handling', 'Every default -- body size limits, request timeouts, memory ceilings -- was tuned for a form submission, not a twenty-gigabyte archive. Large files find every assumption nobody wrote down.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be20-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"large-file-handling-sim"}'::jsonb, '{"xp":234,"credits":45}'::jsonb, false, 3),
  ('mission-be20-04', 'world-be-20', 'campaign-be20', 'operation-be20-1', 'object-storage', 'Object Storage', 'A server''s local disk is not durable, not shared across instances, and not infinite. Object storage exists because a file needs to outlive the machine that received it.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be20-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"object-storage-sim"}'::jsonb, '{"xp":236,"credits":45}'::jsonb, false, 4),
  ('mission-be20-05', 'world-be-20', 'campaign-be20', 'operation-be20-1', 's3-concepts', 'S3 Concepts', 'Buckets, keys and objects -- three ideas, no real folders underneath any of it, no matter how the console draws it. Understand the actual model and a key''s slashes stop being a mystery.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be20-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"s3-concepts-sim"}'::jsonb, '{"xp":238,"credits":45}'::jsonb, false, 5),
  ('mission-be20-06', 'world-be-20', 'campaign-be20', 'operation-be20-1', 'signed-urls', 'Signed URLs', 'A file doesn''t have to pass through the app server to reach storage or come back out of it. A signed URL grants one narrow, time-limited exception directly against the bucket -- and expires whether anyone remembers to revoke it or not.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be20-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"signed-urls-sim"}'::jsonb, '{"xp":240,"credits":46}'::jsonb, false, 6),
  ('mission-be20-07', 'world-be-20', 'campaign-be20', 'operation-be20-2', 'file-metadata', 'File Metadata', 'The object itself is just bytes. Everything that makes those bytes useful -- who uploaded it, what it actually is, whether it''s been scanned -- has to live somewhere else entirely.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be20-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"file-metadata-sim"}'::jsonb, '{"xp":242,"credits":46}'::jsonb, false, 7),
  ('mission-be20-08', 'world-be-20', 'campaign-be20', 'operation-be20-2', 'cdn-delivery', 'CDN Delivery', 'Every download served straight from the origin bucket is a download the origin bucket didn''t need to serve. A CDN puts a copy close to whoever''s asking -- and caches it wrong for exactly as long as nobody sets the headers.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be20-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"cdn-delivery-sim"}'::jsonb, '{"xp":244,"credits":46}'::jsonb, false, 8),
  ('mission-be20-09', 'world-be-20', 'campaign-be20', 'operation-be20-2', 'image-processing-pipelines', 'Image Processing Pipelines', 'Resizing an image is cheap for one image and ruinous for the request path if it happens synchronously, inline, on every single upload. The fix isn''t a faster resize -- it''s not doing it inline at all.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be20-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"image-processing-pipeline-sim"}'::jsonb, '{"xp":246,"credits":47}'::jsonb, false, 9),
  ('mission-be20-10', 'world-be-20', 'campaign-be20', 'operation-be20-2', 'malware-scanning-architecture', 'Malware Scanning Architecture', 'An uploaded file is untrusted the instant it arrives, no matter what its extension claims. Serving it publicly before anything has actually looked inside it is the whole vulnerability, in one sentence.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be20-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"malware-scanning-architecture-sim"}'::jsonb, '{"xp":248,"credits":47}'::jsonb, false, 10),
  ('mission-be20-11', 'world-be-20', 'campaign-be20', 'operation-be20-2', 'resumable-upload-concepts', 'Resumable Upload Concepts', 'A connection drops at ninety-four percent and a naive upload starts over from byte zero. A resumable one only ever needs to ask one question: which bytes actually made it, and where does the next chunk pick up?', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be20-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"resumable-upload-concepts-sim"}'::jsonb, '{"xp":250,"credits":48}'::jsonb, false, 11),
  ('mission-be20-12', 'world-be-20', 'campaign-be20', 'operation-be20-2', 'the-20-gigabyte-upload', 'The 20-Gigabyte Upload', 'The resident''s twenty-gigabyte case archive fails at ninety-four percent, every time, with no error and no way to resume. Everything this Act taught, spent on one upload that refuses to finish.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be20-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"twenty-gigabyte-upload-boss-sim"}'::jsonb, '{"xp":560,"credits":130,"badgeIds":["20-gigabyte-upload"],"skillXp":{"file_storage":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be20-01', 1, 'mira', 'Arc V keeps testing whether what Forge built survives real conditions. This time it isn''t an attacker -- it''s a resident trying to upload a twenty-gigabyte encrypted case archive to the public records portal, and it fails at ninety-four percent, every attempt, with nothing useful in the logs.'),
  ('mission-be20-01', 2, 'forge', 'Ninety-four percent isn''t random. Something specific happens right around there, consistently -- and consistently means it''s not bad luck, it''s a limit nobody wrote down.'),
  ('mission-be20-01', 3, 'mira', 'Before we chase a twenty-gigabyte file, start with the humblest upload there is: a form with a file field in it. Multipart/form-data is still what''s underneath, no matter how big the file gets.'),

  ('mission-be20-02', 1, 'forge', 'A request body isn''t required to show up all at once, and handling it doesn''t require holding all of it in memory either. Streaming reads it in pieces and lets each piece go the moment it''s used.'),
  ('mission-be20-02', 2, 'forge', 'Buffering the whole body before doing anything with it is a choice a lot of code makes by default -- not a rule the protocol forces on anyone.'),

  ('mission-be20-03', 1, 'mira', 'Every default on this server -- body size limit, timeout, memory ceiling -- was tuned assuming a form submission, a profile photo, maybe a PDF. Nobody tuned it for twenty gigabytes, because nobody expected twenty gigabytes.'),
  ('mission-be20-03', 2, 'mira', 'Large files don''t break new rules. They just find every assumption nobody bothered writing down, and stand on it until it gives.'),

  ('mission-be20-04', 1, 'forge', 'A file saved to the app server''s local disk lives exactly as long as that server does, on exactly that one instance. Scale to three instances behind a load balancer and the other two have no idea the file exists.'),
  ('mission-be20-04', 2, 'forge', 'Object storage exists to fix precisely that: durable, shared, and completely decoupled from any one server''s lifecycle.'),

  ('mission-be20-05', 1, 'mira', 'A bucket, a key, an object -- that''s the entire model. A key like case-archives/2024/report.zip looks like a folder path. It isn''t one. It''s a single string, and the slashes are a convention the console draws for you, not a real filesystem underneath.'),
  ('mission-be20-05', 2, 'mira', 'That distinction matters more than it sounds like it should. There''s no folder to list, rename or move -- only keys that happen to share a prefix.'),

  ('mission-be20-06', 1, 'forge', 'A file doesn''t have to round-trip through the app server just because the app server is the thing that authenticated the request. A signed URL is a narrow, time-limited exception, generated once, that lets a client upload or download directly against the bucket.'),
  ('mission-be20-06', 2, 'forge', 'Scope it too broadly, or leave the expiry too far out, and it stops being narrow. It''s still access -- it just doesn''t ask anyone''s permission again once it''s been handed out.'),

  ('mission-be20-07', 1, 'mira', 'The object in the bucket is just bytes. It doesn''t know who uploaded it, what it actually is, or whether anyone''s confirmed it''s safe. All of that has to live somewhere else, tied back to the object by its key.'),
  ('mission-be20-07', 2, 'mira', 'Lose that metadata record and you don''t lose the file -- you lose every reason anyone had to trust it.'),

  ('mission-be20-08', 1, 'forge', 'Every request that hits the origin bucket directly is a request the origin bucket didn''t have to serve. A CDN keeps a copy at an edge location close to whoever''s asking, and only goes back to the origin when it has to.'),
  ('mission-be20-08', 2, 'forge', 'Get the cache headers wrong and it either serves stale data for a week, or never actually caches anything at all -- both look fine right up until someone notices.'),

  ('mission-be20-09', 1, 'forge', 'Resizing one image on upload is nothing. Resizing it synchronously, inline, blocking the response, on every single upload -- that''s a request handler doing work it was never built to survive at volume.'),
  ('mission-be20-09', 2, 'mira', 'This should sound familiar. It''s the same lesson as the job queue, aimed at a different kind of expensive work.'),

  ('mission-be20-10', 1, 'forge', 'An uploaded file is untrusted the moment it arrives, whatever its filename or declared content type claims. Serving it publicly before anything has actually scanned it is the entire vulnerability, in one sentence.'),
  ('mission-be20-10', 2, 'forge', 'The fix isn''t scanning harder. It''s a quarantine bucket the file lands in first, and a public bucket it only ever reaches after a clean result.'),

  ('mission-be20-11', 1, 'mira', 'A connection drops at ninety-four percent and a naive client starts the whole twenty gigabytes over from byte zero. That''s not a bug in the network. That''s an upload design that never asked which bytes actually made it.'),
  ('mission-be20-11', 2, 'mira', 'Resumability only needs one thing tracked honestly: an offset. Where the last acknowledged chunk ended, and where the next one is allowed to begin.'),

  ('mission-be20-12', 1, 'mira', 'This is it -- the resident''s twenty-gigabyte encrypted case archive, failing at ninety-four percent, every single attempt, with nothing in the logs to explain why.'),
  ('mission-be20-12', 2, 'forge', 'I pulled the server''s memory graph during a failed attempt. It climbs steadily through the whole upload and the process dies right around ninety-four percent, every time, at almost exactly the same point.'),
  ('mission-be20-12', 3, 'mira', 'That''s not a coincidence. Find what actually breaks at that point -- not just where the failure shows up.'),
  ('mission-be20-12', 4, 'forge', 'Found it. The upload handler reads the entire request body into one in-memory buffer before writing anything to storage. That buffer was sized for the platform''s old two-hundred-megabyte cap. A twenty-gigabyte file blows past it, and the process runs out of memory before the upload ever completes.'),
  ('mission-be20-12', 5, 'mira', 'So don''t just make the buffer bigger. That fixes this file and fails the next one that''s bigger still. What actually has to change?'),
  ('mission-be20-12', 6, 'forge', 'Stop buffering the whole file at all. Stream it to object storage in chunks as it arrives, track which chunks have landed, and let an interrupted upload resume from the last acknowledged chunk instead of restarting at byte zero.'),
  ('mission-be20-12', 7, 'mira', 'Built. Tested against the resident''s actual file. It finishes -- and it survives a dropped connection at ninety percent without losing the first ninety.'),
  ('mission-be20-12', 8, 'forge', 'Building that meant tracking every large object moving through storage for the first time, not just the ones anyone thought to look at. So I ran a metadata audit while I was in there.'),
  ('mission-be20-12', 9, 'forge', 'Found something. A handful of objects, uploaded over several years, sitting in storage this whole time. Every one of them carries that same doubled-slash tag. Not one of them has ever been downloaded by a human account.'),
  ('mission-be20-12', 10, 'mira', 'Never downloaded. Then what were they uploaded for.'),
  ('mission-be20-12', 11, 'forge', 'I don''t know. I''m not going to guess at an answer I can''t back up -- not off a metadata audit and a tag we''ve been finding in six different places for two Arcs now.'),
  ('mission-be20-12', 12, 'mira', 'File it next to everything else with that tag. Every piece we''ve built now works, and now it holds up under real conditions too. Whether it holds up as a whole system -- real production load, deployed the way production actually deploys -- is a different question. That''s next.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be20-01-o1', 'mission-be20-01', 1, 'Read the raw multipart body', 'Identify the line that defines the boundary separating every part in this request body.'),
  ('mission-be20-01-o2', 'mission-be20-01', 2, 'Choose the right encoding', 'Choose the content type that actually supports plain fields and a binary file in the same request.'),
  ('mission-be20-02-o1', 'mission-be20-02', 1, 'Find the memory leak', 'Debug a handler that holds the entire request body in memory before writing anything to disk.'),
  ('mission-be20-02-o2', 'mission-be20-02', 2, 'Explain the fix', 'Explain why streaming keeps memory use roughly constant regardless of file size.'),
  ('mission-be20-03-o1', 'mission-be20-03', 1, 'Find the hidden ceiling', 'Find the evidence that explains a large-file failure the configured limits don''t account for.'),
  ('mission-be20-04-o1', 'mission-be20-04', 1, 'Diagnose the local-disk problem', 'Explain what actually breaks when a horizontally-scaled service saves files to local disk.'),
  ('mission-be20-05-o1', 'mission-be20-05', 1, 'Match the S3 concept', 'Match each S3 term to what it actually refers to.'),
  ('mission-be20-06-o1', 'mission-be20-06', 1, 'Find the missing expiry', 'Debug a signed-URL generator that never expires once issued.'),
  ('mission-be20-07-o1', 'mission-be20-07', 1, 'Justify the metadata record', 'Find the evidence that explains why the object store alone can''t meet the portal''s own requirement.'),
  ('mission-be20-08-o1', 'mission-be20-08', 1, 'Diagnose the cache header', 'Explain what actually happens when a CDN sits in front of an origin that tells it never to cache.'),
  ('mission-be20-09-o1', 'mission-be20-09', 1, 'Find the blocking work', 'Debug a handler that resizes every uploaded image inline before responding.'),
  ('mission-be20-09-o2', 'mission-be20-09', 2, 'Choose the actual fix', 'Choose the change that fixes this for every upload, not just faster hardware.'),
  ('mission-be20-10-o1', 'mission-be20-10', 1, 'Find the architectural flaw', 'Find the evidence that is the actual flaw in the upload flow, not just a symptom of it.'),
  ('mission-be20-11-o1', 'mission-be20-11', 1, 'Order the resumable flow', 'Put the steps of a resumable upload in the order they actually happen.'),
  ('mission-be20-12-o1', 'mission-be20-12', 1, 'Diagnose the memory failure', 'Find the evidence that is the actual root cause of the failure, not just where it shows up.'),
  ('mission-be20-12-o2', 'mission-be20-12', 2, 'Reject the wrong fixes', 'Choose the change that actually fixes this file, and every larger one after it.'),
  ('mission-be20-12-o3', 'mission-be20-12', 3, 'Design the resumable flow', 'Match each part of the fix to the specific problem it actually solves.'),
  ('mission-be20-12-o4', 'mission-be20-12', 4, 'Ship the fix', 'Synthesize the diagnosis and the fix into what actually ships.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be20-01-o1-c1', 'mission-be20-01-o1', 1, 'code_debugging', 'Which single line establishes the boundary string every part in this body is separated by?', '{"language":"http","code":"POST /uploads HTTP/1.1\nHost: records.nexuscity.io\nContent-Type: multipart/form-data; boundary=----WebKitFormBoundaryAbc123\nContent-Length: 91847\n\n------WebKitFormBoundaryAbc123\nContent-Disposition: form-data; name=\"caseId\"\n\nCASE-4471\n------WebKitFormBoundaryAbc123\nContent-Disposition: form-data; name=\"file\"; filename=\"archive.zip\"\nContent-Type: application/zip\n\n<binary data>\n------WebKitFormBoundaryAbc123--","question":"Which single line establishes the boundary string every part in this body is separated by?"}'::jsonb, '{"requiredLineIds":["Content-Type: multipart/form-data; boundary=----WebKitFormBoundaryAbc123"]}'::jsonb),
  ('mission-be20-01-o2-c1', 'mission-be20-01-o2', 1, 'multiple_choice', 'A form needs to submit both plain text fields and a binary file in the same request. Which content type actually supports that?', '{"question":"A form needs to submit both plain text fields and a binary file in the same request. Which content type actually supports that?","options":[{"id":"a","text":"application/json"},{"id":"b","text":"application/x-www-form-urlencoded"},{"id":"c","text":"multipart/form-data"},{"id":"d","text":"text/plain"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be20-02-o1-c1', 'mission-be20-02-o1', 1, 'code_debugging', 'This handler holds the entire request body in memory before writing anything to disk. Which line is where that memory grows without bound as the file gets larger?', '{"language":"javascript","code":"function handleUpload(req, res) {\n  const chunks = [];\n  req.on(\"data\", (chunk) => {\n    chunks.push(chunk);\n  });\n  req.on(\"end\", () => {\n    const fullBuffer = Buffer.concat(chunks);\n    fs.writeFileSync(\"/tmp/upload\", fullBuffer);\n    res.end(\"ok\");\n  });\n}","question":"This handler holds the entire request body in memory before writing anything to disk. Which line is where that memory grows without bound as the file gets larger?"}'::jsonb, '{"requiredLineIds":["    chunks.push(chunk);"]}'::jsonb),
  ('mission-be20-02-o2-c1', 'mission-be20-02-o2', 1, 'multiple_choice', 'Why does streaming a file to disk as it arrives avoid the memory blowup buffering causes?', '{"question":"Why does streaming a file to disk as it arrives avoid the memory blowup buffering causes?","options":[{"id":"a","text":"It doesn''t matter -- disks are always slower than memory anyway"},{"id":"b","text":"Streaming writes each chunk to its destination as it arrives, so memory usage stays roughly constant no matter how large the file gets"},{"id":"c","text":"Streaming makes the network transfer itself faster"},{"id":"d","text":"Streaming is only relevant for video files"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be20-03-o1-c1', 'mission-be20-03-o1', 1, 'investigation', 'Which evidence explains why a twenty-gigabyte upload can still fail even though the configured limits look generous enough?', '{"evidence":[{"id":"ev1","label":"Temp directory mount","detail":"The server''s /tmp directory, where in-progress uploads are staged before moving to permanent storage, is mounted as a 2GB in-memory tmpfs."},{"id":"ev2","label":"Body size limit","detail":"The reverse proxy''s max body size is configured at 25GB -- comfortably above any file the portal expects to accept."},{"id":"ev3","label":"Request timeout","detail":"The upload endpoint''s request timeout is set to 300 seconds, far longer than a typical form submission would ever need."}],"question":"Which evidence explains why a twenty-gigabyte upload can still fail even though the configured limits look generous enough?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be20-04-o1-c1', 'mission-be20-04-o1', 1, 'multiple_choice', 'A service now runs on three interchangeable instances behind a load balancer, and files are currently saved to each instance''s local disk. What actually goes wrong?', '{"question":"A service now runs on three interchangeable instances behind a load balancer, and files are currently saved to each instance''s local disk. What actually goes wrong?","options":[{"id":"a","text":"Nothing, as long as the disk has enough space"},{"id":"b","text":"A file uploaded through instance A doesn''t exist on instances B or C, so a later download can fail depending on which instance handles it -- and any instance restarting loses its files entirely"},{"id":"c","text":"Local disks are always slower than network storage"},{"id":"d","text":"This only matters for files larger than 1GB"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be20-05-o1-c1', 'mission-be20-05-o1', 1, 'drag_and_drop', 'Match each S3 term to what it actually refers to.', '{"items":[{"id":"c1","text":"Bucket"},{"id":"c2","text":"Key"},{"id":"c3","text":"Object"},{"id":"c4","text":"Region"}],"targets":[{"id":"t1","label":"The top-level named container everything is stored inside"},{"id":"t2","label":"The unique string identifying one object inside a bucket -- slashes in it are just characters, not real folders"},{"id":"t3","label":"The actual file plus its metadata, stored under one key"},{"id":"t4","label":"The physical location a bucket''s data actually lives in, chosen for latency and compliance"}]}'::jsonb, '{"correctMapping":{"c1":"t1","c2":"t2","c3":"t3","c4":"t4"}}'::jsonb),

  ('mission-be20-06-o1-c1', 'mission-be20-06-o1', 1, 'code_debugging', 'This signed URL never expires once generated, and can be reused by anyone who gets a copy of it. Which line is where the missing expiry belongs, inside the params object?', '{"language":"typescript","code":"function getUploadUrl(bucket: string, key: string) {\n  const params = {\n    Bucket: bucket,\n    Key: key,\n  };\n  return s3.getSignedUrl(\"putObject\", params);\n}","question":"This signed URL never expires once generated, and can be reused by anyone who gets a copy of it. Which line is where the missing expiry belongs, inside the params object?"}'::jsonb, '{"requiredLineIds":["    Key: key,"]}'::jsonb),

  ('mission-be20-07-o1-c1', 'mission-be20-07-o1', 1, 'investigation', 'Which evidence explains why the object store alone can''t answer the portal''s own requirement?', '{"evidence":[{"id":"ev1","label":"Object listing","detail":"The bucket contains a key case-archives/2024/CASE-4471.zip with no other information attached to it inside the object store itself."},{"id":"ev2","label":"Portal requirement","detail":"The records portal needs to show every resident which cases they''ve uploaded, when, and whether the file has passed a malware scan -- before anyone downloads it."},{"id":"ev3","label":"Metadata table","detail":"A separate database row keyed by the same object key stores uploader_id, original_filename, content_type, size_bytes and scan_status."}],"question":"Which evidence explains why the object store alone can''t answer the portal''s own requirement?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be20-08-o1-c1', 'mission-be20-08-o1', 1, 'multiple_choice', 'A CDN is placed in front of the origin bucket, but every response carries Cache-Control: no-store. What actually happens?', '{"question":"A CDN is placed in front of the origin bucket, but every response carries Cache-Control: no-store. What actually happens?","options":[{"id":"a","text":"Nothing changes -- no-store is ignored by CDNs"},{"id":"b","text":"The CDN never caches anything, so every request still round-trips to the origin bucket -- the CDN adds latency without removing any load"},{"id":"c","text":"The CDN caches forever regardless of the header"},{"id":"d","text":"no-store only affects browsers, not CDNs"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be20-09-o1-c1', 'mission-be20-09-o1', 1, 'code_debugging', 'This handler resizes every uploaded image inline before responding, blocking the request the whole time. Which line is the expensive work that shouldn''t run inside the request path?', '{"language":"javascript","code":"app.post(\"/uploads\", async (req, res) => {\n  const file = await saveToStorage(req);\n  const thumbnail = await resizeImage(file, { width: 200 });\n  await saveToStorage(thumbnail);\n  res.json({ status: \"uploaded\" });\n});","question":"This handler resizes every uploaded image inline before responding, blocking the request the whole time. Which line is the expensive work that shouldn''t run inside the request path?"}'::jsonb, '{"requiredLineIds":["  const thumbnail = await resizeImage(file, { width: 200 });"]}'::jsonb),
  ('mission-be20-09-o2-c1', 'mission-be20-09-o2', 1, 'multiple_choice', 'What''s the actual fix here -- not just a faster resize?', '{"question":"What''s the actual fix here -- not just a faster resize?","options":[{"id":"a","text":"Use a smaller thumbnail size"},{"id":"b","text":"Enqueue a background job to generate the thumbnail after the upload response has already been sent"},{"id":"c","text":"Resize on the client before uploading"},{"id":"d","text":"Cache the resize result"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be20-10-o1-c1', 'mission-be20-10-o1', 1, 'investigation', 'Which evidence is the actual architectural flaw here, not just a symptom of it?', '{"evidence":[{"id":"ev1","label":"Upload flow","detail":"A file is written directly to the public-facing bucket at the moment the upload completes, before any scan has run."},{"id":"ev2","label":"Average detection time","detail":"The scanner correctly flags and deletes infected files it eventually gets to, on average four minutes after upload."},{"id":"ev3","label":"Team rationale","detail":"This was designed so residents see their file immediately after upload, without waiting on the scan queue."}],"question":"Which evidence is the actual architectural flaw here, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be20-11-o1-c1', 'mission-be20-11-o1', 1, 'interactive_diagram', 'Order the resumable upload flow from session start to completion.', '{"diagramId":"resumable-upload-flow","hotspots":[{"id":"init","label":"Client requests an upload session","explanation":"The client asks the server for an upload id and the chunk size it should use."},{"id":"session","label":"Server returns an upload id and offset 0","explanation":"The server creates a tracking record for this upload and tells the client where to start."},{"id":"chunk","label":"Client uploads a chunk and receives the new offset","explanation":"Each chunk is sent with its position; the server acknowledges how many bytes have been durably received so far."},{"id":"resume","label":"On disconnect, client asks for the current offset","explanation":"Instead of restarting at byte zero, the client asks the server how far the upload actually got."},{"id":"continue","label":"Client resumes from the last acknowledged offset","explanation":"Only the bytes that never arrived get re-sent."},{"id":"complete","label":"Server assembles and confirms completion","explanation":"Once every chunk is accounted for, the server finalizes the object and confirms the upload is done."}],"task":"Order the resumable upload flow from session start to completion."}'::jsonb, '{"correctOrderIds":["init","session","chunk","resume","continue","complete"]}'::jsonb),

  ('mission-be20-12-o1-c1', 'mission-be20-12-o1', 1, 'investigation', 'Which evidence is the actual root cause of the failure, not just where or when it shows up?', '{"evidence":[{"id":"ev1","label":"Memory graph","detail":"Server memory climbs steadily through the entire upload and the process is OOM-killed at almost exactly ninety-four percent, every single attempt."},{"id":"ev2","label":"Buffer allocation","detail":"The upload handler allocates one in-memory buffer sized for the platform''s previous two-hundred-megabyte upload cap, then reads the entire request body into it before writing anything to storage."},{"id":"ev3","label":"Platform history","detail":"The two-hundred-megabyte cap was raised to unlimited eight months ago when the records portal added support for large case archives; the upload handler itself was never revisited."}],"question":"Which evidence is the actual root cause of the failure, not just where or when it shows up?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be20-12-o2-c1', 'mission-be20-12-o2', 1, 'multiple_choice', 'Given the root cause, which change actually fixes this -- for this file and every larger one after it?', '{"question":"Given the root cause, which change actually fixes this -- for this file and every larger one after it?","options":[{"id":"a","text":"Increase the in-memory buffer to comfortably fit twenty gigabytes"},{"id":"b","text":"Raise the request timeout so the upload has more time to complete"},{"id":"c","text":"Stream the upload to object storage in fixed-size chunks as they arrive, instead of buffering the whole file in memory at once"},{"id":"d","text":"Compress the file client-side before uploading"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be20-12-o3-c1', 'mission-be20-12-o3', 1, 'drag_and_drop', 'Match each part of the fix to the specific problem it actually solves.', '{"items":[{"id":"i1","text":"Streaming the body directly to object storage in chunks"},{"id":"i2","text":"Tracking each chunk''s offset in a durable upload-session record"},{"id":"i3","text":"Letting the client query the last acknowledged offset after a disconnect"}],"targets":[{"id":"t1","label":"Removes the unbounded in-memory buffer entirely"},{"id":"t2","label":"Makes it possible to know exactly which bytes already landed"},{"id":"t3","label":"Lets an interrupted upload resume instead of restarting from byte zero"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),
  ('mission-be20-12-o4-c1', 'mission-be20-12-o4', 1, 'boss_encounter', 'Having diagnosed the failure and chosen the real fix, confirm what actually ships.', '{"stages":[{"objectiveRef":"mission-be20-12-o1","label":"Diagnose the memory failure"},{"objectiveRef":"mission-be20-12-o2","label":"Reject the wrong fixes"},{"objectiveRef":"mission-be20-12-o3","label":"Design the resumable flow"}],"task":"Having diagnosed the failure and chosen the real fix, confirm what actually ships: the handler stops buffering the whole file in memory, streams it to object storage in tracked chunks, and lets an interrupted upload resume from its last acknowledged offset instead of restarting from byte zero."}'::jsonb, '{"requiredObjectiveIds":["mission-be20-12-o1","mission-be20-12-o2","mission-be20-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be20-01-o1-c1', 'orientation', 'Headers describe the request. Exactly one header line names the string that separates every part below it.', 10, 1),
  ('mission-be20-01-o1-c1', 'concept', 'The boundary named in the Content-Type header has to match the delimiter lines that actually appear in the body, or nothing downstream can be split apart correctly.', 20, 2),
  ('mission-be20-01-o1-c1', 'solution', 'The Content-Type header declares boundary=----WebKitFormBoundaryAbc123 -- that string is what every ------WebKitFormBoundaryAbc123 delimiter line in the body has to match.', 30, 3),
  ('mission-be20-01-o2-c1', 'orientation', 'One of these formats is built specifically to carry binary data alongside plain fields in one request.', 10, 1),
  ('mission-be20-01-o2-c1', 'solution', 'multipart/form-data splits the body into named parts, one of which can be raw binary -- JSON and urlencoded both assume text-only values.', 20, 2),

  ('mission-be20-02-o1-c1', 'orientation', 'Every chunk that arrives gets kept, not released -- follow where each one ends up.', 10, 1),
  ('mission-be20-02-o1-c1', 'concept', 'An array that only ever grows for the lifetime of the request holds the entire file in memory by the time the last chunk arrives, no matter how the chunks arrived.', 20, 2),
  ('mission-be20-02-o1-c1', 'solution', 'chunks.push(chunk) keeps every chunk in memory for the whole request -- by end, chunks holds the entire file at once.', 30, 3),
  ('mission-be20-02-o2-c1', 'orientation', 'Compare what''s held in memory at any one moment under each approach.', 10, 1),
  ('mission-be20-02-o2-c1', 'solution', 'b: writing each chunk to disk as it arrives means only one chunk needs to be in memory at a time, regardless of total file size.', 20, 2),

  ('mission-be20-03-o1-c1', 'orientation', 'Two of these limits were raised generously. One was never actually raised at all.', 10, 1),
  ('mission-be20-03-o1-c1', 'concept', 'A tmpfs mount is backed by RAM, not disk -- its capacity is fixed regardless of what any application-level body size limit or timeout allows.', 20, 2),
  ('mission-be20-03-o1-c1', 'solution', 'ev1: /tmp being a 2GB tmpfs caps in-progress uploads at 2GB no matter what the proxy''s body size limit or the timeout say.', 30, 3),

  ('mission-be20-04-o1-c1', 'orientation', 'Ask what a request routed to instance B knows about a file that only ever touched instance A.', 10, 1),
  ('mission-be20-04-o1-c1', 'solution', 'b: local disk is per-instance -- other instances can''t see the file, and a restarted instance loses whatever it had entirely.', 20, 2),

  ('mission-be20-05-o1-c1', 'orientation', 'One term is the container, one is the address inside it, one is the thing itself, one is where it physically lives.', 10, 1),
  ('mission-be20-05-o1-c1', 'solution', 'Bucket -> container, Key -> address string (no real folders), Object -> the file plus its metadata, Region -> physical location.', 20, 2),

  ('mission-be20-06-o1-c1', 'orientation', 'Nothing in this params object tells S3 how long the signature should remain valid.', 10, 1),
  ('mission-be20-06-o1-c1', 'concept', 'A signed URL without an explicit expiry defaults to remaining valid far longer than intended -- the fix is adding an Expires field to the same params object being passed to getSignedUrl.', 20, 2),
  ('mission-be20-06-o1-c1', 'solution', 'The params object -- right after Key: key, -- is missing an Expires field; without it the signed URL has no meaningful lifetime.', 30, 3),

  ('mission-be20-07-o1-c1', 'orientation', 'Two of these describe the object store''s side. One describes what the application actually needs to show.', 10, 1),
  ('mission-be20-07-o1-c1', 'concept', 'The object store can hold bytes under a key, but it was never designed to answer application-level questions like ownership, upload time or scan status.', 20, 2),
  ('mission-be20-07-o1-c1', 'solution', 'ev2: the portal''s own requirement -- uploader, timestamp, scan status, shown before download -- is exactly what the object store has no way to answer on its own.', 30, 3),

  ('mission-be20-08-o1-c1', 'orientation', 'no-store is an instruction about caching, and it applies to every cache in the path, not just the browser.', 10, 1),
  ('mission-be20-08-o1-c1', 'solution', 'b: no-store tells the CDN never to cache the response, so every request still travels all the way back to the origin bucket.', 20, 2),

  ('mission-be20-09-o1-c1', 'orientation', 'Saving the original file is fast. One of these lines is doing real, variable-cost work before the response goes out.', 10, 1),
  ('mission-be20-09-o1-c1', 'concept', 'Image resizing is CPU-bound and its cost scales with image size and volume -- running it inline means every request pays that cost before the client gets a response.', 20, 2),
  ('mission-be20-09-o1-c1', 'solution', 'const thumbnail = await resizeImage(...) is the expensive, variable-cost work blocking the response for every upload.', 30, 3),
  ('mission-be20-09-o2-c1', 'orientation', 'The fix changes when the work happens, not how fast it happens.', 10, 1),
  ('mission-be20-09-o2-c1', 'solution', 'b: move the resize into a background job after the response is sent -- the request path stops paying for it entirely.', 20, 2),

  ('mission-be20-10-o1-c1', 'orientation', 'One entry describes the design decision itself. The others describe its consequences.', 10, 1),
  ('mission-be20-10-o1-c1', 'concept', 'Writing to the public bucket before a scan has run means every file is downloadable during the exact window it hasn''t been verified safe yet.', 20, 2),
  ('mission-be20-10-o1-c1', 'solution', 'ev1: writing the file straight to the public bucket before any scan runs is the actual flaw -- ev2 and ev3 just describe how long that window stays open and why it was built that way.', 30, 3),

  ('mission-be20-11-o1-c1', 'orientation', 'Nobody can be told to resume something that was never tracked as having started.', 10, 1),
  ('mission-be20-11-o1-c1', 'concept', 'Separate the happy path from the recovery path: a session and offset have to exist before any chunk is sent, and a disconnect has to be detected before resuming makes sense.', 20, 2),
  ('mission-be20-11-o1-c1', 'solution', 'Request a session, get an offset of 0, upload chunks and receive updated offsets, ask for the current offset after a disconnect, resume from it, then the server assembles and confirms completion.', 30, 3),

  ('mission-be20-12-o1-c1', 'orientation', 'One entry is the symptom. One is the timeline. One is the actual mechanism that fails.', 10, 1),
  ('mission-be20-12-o1-c1', 'concept', 'A buffer sized for a two-hundred-megabyte cap doesn''t grow just because the platform''s upload limit was raised elsewhere -- the handler itself has to be changed for the new limit to actually hold.', 20, 2),
  ('mission-be20-12-o1-c1', 'solution', 'ev2: the handler still allocates one in-memory buffer sized for the old 200MB cap and reads the whole body into it -- that''s the mechanism the OOM kill and the outdated cap are both downstream of.', 30, 3),

  ('mission-be20-12-o2-c1', 'orientation', 'Two of these options treat the symptom. One changes the actual mechanism.', 10, 1),
  ('mission-be20-12-o2-c1', 'solution', 'c: streaming to storage in chunks removes the unbounded in-memory buffer entirely -- a bigger buffer or a longer timeout both just delay the same failure at a larger size.', 20, 2),

  ('mission-be20-12-o3-c1', 'orientation', 'Each change closes one specific gap from the diagnosis -- match them one to one.', 10, 1),
  ('mission-be20-12-o3-c1', 'solution', 'Streaming removes the buffer, offset tracking makes progress knowable, and querying the offset after a disconnect is what makes resuming possible at all.', 20, 2),

  ('mission-be20-12-o4-c1', 'orientation', 'Line up the diagnosis, the rejected fixes, and the resumable design into one sentence describing what ships.', 15, 1),
  ('mission-be20-12-o4-c1', 'solution', 'The fix that ships: stop buffering the whole file in memory, stream it to object storage in tracked chunks, and let an interrupted upload resume from its last acknowledged offset instead of restarting from byte zero.', 25, 2);
